	attrTypes["failing"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["not_applicable"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["passing"] = basetypes.Int64Type{}.TerraformType(ctx)
